const frame = msg.payload || msg;
const canId = frame.canid;
const data = frame.data || [];

let state = flow.get("batteryInfo") || {
    kind: "BatteryInfoState",
    version: 1,
    manufacturerName: null,
    moduleCount: 0,
    bmsList: []
};

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function getBms(addr) {
    var bms = state.bmsList.find(function(b) { return b.bmsAddress === addr; });
    if (!bms) {
        bms = { bmsAddress: addr, _sn1: "", _sn2: "", _sn3: "" };
        state.bmsList.push(bms);
        state.bmsList.sort(function(a, b) { return a.bmsAddress - b.bmsAddress; });
    }
    return bms;
}

var processed = false;

if (canId === 0x359) {
    processed = true;
    state.moduleCount = data[4];
}

if (canId === 0x35E) {
    processed = true;
    var name = "";
    for (var i = 0; i < 8; i++) {
        if (data[i] === 0) break;
        name += String.fromCharCode(data[i]);
    }
    state.manufacturerName = name;
}

if ((canId & 0x1FFFF000) === 0x14F00000) {
    var msgType = (canId >> 8) & 0x0F;
    var bmsAddr = canId & 0xFF;

    if (msgType >= 3 && msgType <= 7) {
        processed = true;
        var bms = getBms(bmsAddr);

        switch (msgType) {
            case 3:
                bms.ratedCapacityAh = u16(data, 0) * 0.01;
                break;
            case 4:
                bms.softwareVersionMain = data[0];
                bms.softwareVersionSub = data[1];
                break;
            case 5:
                bms._sn1 = "";
                for (var j = 0; j < 8; j++) {
                    if (data[j] === 0) break;
                    bms._sn1 += String.fromCharCode(data[j]);
                }
                bms.serialNumber = bms._sn1 + (bms._sn2 || "") + (bms._sn3 || "");
                break;
            case 6:
                bms._sn2 = "";
                for (var k = 0; k < 8; k++) {
                    if (data[k] === 0) break;
                    bms._sn2 += String.fromCharCode(data[k]);
                }
                bms.serialNumber = (bms._sn1 || "") + bms._sn2 + (bms._sn3 || "");
                break;
            case 7:
                bms._sn3 = "";
                for (var l = 0; l < 8; l++) {
                    if (data[l] === 0) break;
                    bms._sn3 += String.fromCharCode(data[l]);
                }
                bms.serialNumber = (bms._sn1 || "") + (bms._sn2 || "") + bms._sn3;
                break;
        }
    }
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("batteryInfo", state);
msg.payload = state;
return msg;

var state = flow.get("batteryInfo");
if (state) {
    var clean = JSON.parse(JSON.stringify(state));
    clean.bmsList.forEach(function(bms) {
        delete bms._sn1;
        delete bms._sn2;
        delete bms._sn3;
    });
    msg.payload = clean;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
